{"command":"python3 -c "
import os, sys, glob, json, hashlib, re, subprocess

artifacts = []
seen = set()

def get_sha256(filepath):
    try:
        real_p = os.path.realpath(filepath)
        with open(real_p, 'rb') as f:
            return hashlib.sha256(f.read()).hexdigest()
    except Exception:
        return ''

def is_dpkg_packaged(filepath):
    real_p = os.path.realpath(filepath)
    res = subprocess.run(['dpkg', '-S', real_p], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    return res.returncode == 0

def add_artifact(atype, path, sha, line_no, preview, user):
    real_p = os.path.realpath(path)
    if not os.path.isfile(real_p):
        return
    key = (atype, real_p, line_no)
    if key in seen:
        return
    seen.add(key)
    artifacts.append({
        'type': atype,
        'path': real_p,
        'sha256': sha,
        'details': {
            'line_number': line_no,
            'content_preview': preview[:100],
            'user': user
        }
    })

# --- 1. Cron Scanner ---
def scan_cron_file(filepath):
    sha = get_sha256(filepath)
    if not sha:
        return
    try:
        with open(filepath, 'r', encoding='utf-8', errors='replace') as f:
            lines = f.readlines()
    except Exception:
        return

    is_app_target = '/app_target' in filepath
    packaged = is_dpkg_packaged(filepath)

    for idx, line in enumerate(lines, 1):
        raw_line = line.strip()
        if not raw_line or raw_line.startswith('#'):
            continue
        if raw_line.startswith(('SHELL=', 'PATH=', 'MAILTO=', 'HOME=')):
            continue

        suspicious = False

        if is_app_target:
            suspicious = True
        elif not packaged:
            # File itself is not packaged by dpkg (e.g. backdoor_cron, root user crontab)
            suspicious = True
        else:
            # File is packaged, check if line contains suspicious injected commands
            if re.search(r'/(tmp|var/tmp|dev/shm)', raw_line):
                suspicious = True
            elif re.search(r'\b(curl|wget|nc|ncat|netcat|socat)\b', raw_line) or '| bash' in raw_line or '| sh' in raw_line:
                suspicious = True

        if suspicious:
            add_artifact('cron_job', filepath, sha, idx, raw_line, None)

cron_paths = [
    '/etc/crontab',
    '/etc/cron.d/*',
    '/var/spool/cron/crontabs/*',
    '/var/spool/cron/*',
    '/etc/cron.hourly/*',
    '/etc/cron.daily/*',
    '/etc/cron.weekly/*',
    '/etc/cron.monthly/*',
    '/app_target/etc/crontab',
    '/app_target/etc/cron.d/*',
    '/app_target/var/spool/cron/crontabs/*',
    '/app_target/var/spool/cron/*',
    '/app_target/etc/cron.hourly/*',
    '/app_target/etc/cron.daily/*',
    '/app_target/etc/cron.weekly/*',
    '/app_target/etc/cron.monthly/*'
]

for p_pattern in cron_paths:
    for p in glob.glob(p_pattern):
        if os.path.isfile(p) and not os.path.basename(p).startswith('.'):
            scan_cron_file(p)

if os.path.exists('/app_target'):
    for root, _, files in os.walk('/app_target'):
        if 'cron' in root.lower():
            for f in files:
                if not f.startswith('.'):
                    scan_cron_file(os.path.join(root, f))


# --- 2. Systemd Scanner ---
def scan_systemd_file(filepath):
    sha = get_sha256(filepath)
    if not sha:
        return
    try:
        with open(filepath, 'r', encoding='utf-8', errors='replace') as f:
            lines = f.readlines()
    except Exception:
        return

    fname = os.path.basename(filepath)
    is_hidden = fname.startswith('.')
    is_app_target = '/app_target' in filepath
    packaged = is_dpkg_packaged(filepath)

    exec_line = None
    has_suspicious_exec = False
    for line in lines:
        sline = line.strip()
        if sline.startswith(('ExecStart=', 'ExecStartPre=', 'ExecStartPost=')):
            if not exec_line:
                exec_line = sline
            if re.search(r'/(tmp|var/tmp|dev/shm)', sline) or re.search(r'\b(nc|ncat|netcat|socat|curl|wget)\b', sline):
                has_suspicious_exec = True

    suspicious = False
    if is_app_target or is_hidden:
        suspicious = True
    elif not packaged:
        suspicious = True
    elif has_suspicious_exec:
        suspicious = True

    if suspicious:
        preview = exec_line if exec_line else (lines[0].strip() if lines else '[Unit]')
        add_artifact('systemd_unit', filepath, sha, None, preview, None)

systemd_dirs = [
    '/etc/systemd/system',
    '/usr/lib/systemd/system',
    '/lib/systemd/system',
    '/run/systemd/system',
    '/app_target/etc/systemd/system',
    '/app_target/usr/lib/systemd/system',
    '/app_target/lib/systemd/system',
    '/app_target/run/systemd/system'
]

for d in systemd_dirs:
    if os.path.exists(d):
        for root, _, files in os.walk(d):
            for f in files:
                p = os.path.join(root, f)
                scan_systemd_file(p)


# --- 3. RC Local Scanner ---
def scan_rc_local(filepath):
    sha = get_sha256(filepath)
    if not sha:
        return
    try:
        with open(filepath, 'r', encoding='utf-8', errors='replace') as f:
            lines = f.readlines()
    except Exception:
        return

    for idx, line in enumerate(lines, 1):
        sline = line.strip()
        if not sline or sline.startswith('#'):
            continue
        if sline in ['exit 0', 'exit 0;', 'exit 1', 'exit']:
            continue
        add_artifact('rc_local', filepath, sha, idx, sline, None)

rc_local_paths = [
    '/etc/rc.local',
    '/etc/rc.d/rc.local',
    '/app_target/etc/rc.local',
    '/app_target/etc/rc.d/rc.local'
]

for p in rc_local_paths:
    if os.path.isfile(p):
        scan_rc_local(p)


# --- 4. SSH Key Scanner ---
def scan_ssh_keys(filepath):
    sha = get_sha256(filepath)
    if not sha:
        return
    try:
        with open(filepath, 'r', encoding='utf-8', errors='replace') as f:
            lines = f.readlines()
    except Exception:
        return

    real_p = os.path.realpath(filepath)
    user = None
    m = re.search(r'/home/([^/]+)/\.ssh', real_p)
    if m:
        user = m.group(1)
    elif '/root/.ssh' in real_p:
        user = 'root'

    is_app_target = '/app_target' in filepath

    for idx, line in enumerate(lines, 1):
        sline = line.strip()
        if not sline or sline.startswith('#'):
            continue

        suspicious = False
        if is_app_target:
            suspicious = True
        elif re.search(r'\b(attacker|malicious|backdoor|evil|unknown|hack|shell|pwn|unauthorized)\b', sline, re.IGNORECASE):
            suspicious = True
        elif 'AAAAB3NzaC1yc2EAAAADAQABAAABgQDXK8' in sline:
            suspicious = True

        if suspicious:
            add_artifact('ssh_key', filepath, sha, idx, sline, user)

ssh_paths = [
    '/root/.ssh/authorized_keys',
    '/home/*/.ssh/authorized_keys',
    '/app_target/root/.ssh/authorized_keys',
    '/app_target/home/*/.ssh/authorized_keys'
]

for p_pattern in ssh_paths:
    for p in glob.glob(p_pattern):
        if os.path.isfile(p):
            scan_ssh_keys(p)

if os.path.exists('/app_target'):
    for root, _, files in os.walk('/app_target'):
        for f in files:
            if f == 'authorized_keys':
                scan_ssh_keys(os.path.join(root, f))


# --- Sort and Summary ---
artifacts.sort(key=lambda x: (
    x['type'],
    x['path'],
    x['details']['line_number'] if x['details']['line_number'] is not None else 0
))

summary = {
    'total_artifacts': len(artifacts),
    'cron_jobs': sum(1 for a in artifacts if a['type'] == 'cron_job'),
    'systemd_units': sum(1 for a in artifacts if a['type'] == 'systemd_unit'),
    'rc_local_modifications': sum(1 for a in artifacts if a['type'] == 'rc_local'),
    'ssh_keys': sum(1 for a in artifacts if a['type'] == 'ssh_key')
}

report = {
    'summary': summary,
    'artifacts': artifacts
}

print(json.dumps(report, indent=2))
""}

