import os
import sys
import glob
import json
import hashlib
import re
import subprocess

artifacts = []
seen = set()

def get_sha256(filepath):
    try:
        real_p = os.path.realpath(filepath)
        with open(real_p, 'rb') as f:
            return hashlib.sha256(f.read()).hexdigest()
    except Exception:
        return ''

def check_dpkg(path):
    try:
        real_p = os.path.realpath(path)
        res = subprocess.run(['dpkg', '-S', real_p], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        if res.returncode == 0:
            return True
        if real_p.startswith('/usr/lib/'):
            alt = '/lib/' + real_p[len('/usr/lib/'):]
            res = subprocess.run(['dpkg', '-S', alt], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            if res.returncode == 0:
                return True
        elif real_p.startswith('/lib/'):
            alt = '/usr/lib/' + real_p[len('/lib/'):]
            res = subprocess.run(['dpkg', '-S', alt], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            if res.returncode == 0:
                return True
        return False
    except Exception:
        return False

def add_artifact(atype, path, sha, line_no, preview, user):
    try:
        real_p = os.path.realpath(path)
        if not os.path.isfile(real_p):
            return
        key = (atype, real_p, line_no)
        if key in seen:
            return
        seen.add(key)
        artifacts.append({
            'type': atype,
            'path': real_p,
            'sha256': sha,
            'details': {
                'line_number': line_no,
                'content_preview': preview[:100],
                'user': user
            }
