    except Exception:
        pass

# --- 1. Cron Scanner ---
def scan_cron_file(filepath):
    try:
        sha = get_sha256(filepath)
        if not sha:
            return
        with open(filepath, 'r', encoding='utf-8', errors='replace') as f:
            lines = f.readlines()

        is_app_target = '/app_target' in filepath
        packaged = check_dpkg(filepath)

        for idx, line in enumerate(lines, 1):
            raw_line = line.strip()
            if not raw_line or raw_line.startswith('#'):
                continue
            if raw_line.startswith(('SHELL=', 'PATH=', 'MAILTO=', 'HOME=')):
                continue

