                continue
            if sline in ['exit 0', 'exit 0;', 'exit 1', 'exit']:
                continue
            add_artifact('rc_local', filepath, sha, idx, sline, None)
    except Exception:
        pass

rc_local_paths = [
    '/etc/rc.local',
    '/etc/rc.d/rc.local',
    '/app_target/etc/rc.local',
    '/app_target/etc/rc.d/rc.local'
]

for p in rc_local_paths:
    if os.path.isfile(p):
        scan_rc_local(p)


# --- 4. SSH Key Scanner ---
def scan_ssh_keys(filepath):
    try:
        sha = get_sha256(filepath)
        if not sha:
            return
        with open(filepath, 'r', encoding='utf-8', errors='replace') as f:
            lines = f.readlines()

        real_p = os.path.realpath(filepath)
        user = None
        m_home = re.search(r'/home/([^/]+)/\.ssh', real_p)
        if m_home:
            user = m_home.group(1)
        elif '/root/.ssh' in real_p:
            user = 'root'
        else:
            m_gen = re.search(r'/([^/]+)/\.ssh', real_p)
            if m_gen and m_gen.group(1) not in ('home', 'root', 'app_target'):
                user = m_gen.group(1)

        is_app_target = '/app_target' in filepath

        for idx, line in enumerate(lines, 1):
            sline = line.strip()
            if not sline or sline.startswith('#'):
                continue

            suspicious = False
            if is_app_target:
                suspicious = True
            elif re.search(r'\b(attacker|malicious|backdoor|evil|unknown|hack|shell|pwn|unauthorized)\b', sline, re.IGNORECASE):
                suspicious = True
            elif 'AAAAB3NzaC1yc2EAAAADAQABAAABgQDXK8' in sline:
                suspicious = True

            if suspicious:
                add_artifact('ssh_key', filepath, sha, idx, sline, user)
    except Exception:
        pass

ssh_patterns = [
    '/root/.ssh/authorized_keys',
    '/home/*/.ssh/authorized_keys',
    '/app_target/root/.ssh/authorized_keys',
    '/app_target/home/*/.ssh/authorized_keys'
]

for p_pattern in ssh_patterns:
    try:
        for p in glob.glob(p_pattern):
            if os.path.isfile(p):
                scan_ssh_keys(p)
    except Exception:
        pass

if os.path.exists('/app_target'):
    try:
        for root, _, files in os.walk('/app_target'):
            for f in files:
